/*
 * FUNCTION DELETE <LIBRARY NAME>
 */
void functionDeleteCommand(client *c) {
    if (curr_functions_lib_ctx == NULL) {
        addReplyError(c, "Function library is not initialized");
        return;
    }
    robj *function_name = c->argv[2];
    functionLibInfo *li = dictFetchValue(curr_functions_lib_ctx->libraries, function_name->ptr);
    if (!li) {
        addReplyError(c, "Library not found");
        return;
    }

    libraryUnlink(curr_functions_lib_ctx, li);
    engineLibraryFree(li);
    /* Indicate that the command changed the data so it will be replicated and
     * counted as a data change (for persistence configuration) */
    server.dirty++;
    addReply(c, shared.ok);
}

/* FUNCTION KILL */
void functionKillCommand(client *c) {
    if (curr_functions_lib_ctx == NULL) {
        addReplyError(c, "Function library is not initialized");
        return;
    }
    functionsScriptKill(c, 0);
}

/* Try to extract command flags if we can, returns the modified flags.
 * Note that it does not guarantee the command arguments are right. */
uint64_t fcallGetCommandFlags(client *c, uint64_t cmd_flags) {
    functionsLibCtx *live_ctx = curr_functions_lib_ctx;
    if (!functionsCommandIsFcall(c))
        return cmd_flags;
    robj *function_name = c->argv[1];
    functionInfo *fi = dictFetchValue(live_ctx->functions, function_name->ptr);
    if (!fi)
        return cmd_flags;
    uint64_t script_flags = functionsNormalizeDeclaredFlags(functionsInfoFlags(fi));
    return functionsScriptFlagsToCmdFlags(cmd_flags, script_flags);
}

static void fcallCommandGeneric(client *c, int ro) {
    functionsLibCtx *live_ctx = curr_functions_lib_ctx;
    robj *function_name = c->argv[1];
    functionInfo *fi = dictFetchValue(live_ctx->functions, function_name->ptr);
    if (!fi || !functionsFunctionExists(live_ctx, function_name->ptr)) {
        sds missing = functionsDescribeMissingFunction(function_name->ptr);
        addReplyError(c, missing);
        sdsfree(missing);
        return;
    }
    engine *engine = fi->li->ei->engine;

    long long numkeys;
    /* Get the number of arguments that are keys */
    if (functionsValidateKeyCount(c, 2, &numkeys) != C_OK) {
        return;
    }

    scriptRunCtx run_ctx;

    if (functionsScriptPrepareForRun(&run_ctx, fi->li->ei->c, c, fi->name, fi->f_flags, ro) != C_OK)
        return;

    engine->call(&run_ctx, engine->engine_ctx, fi->function, c->argv + 3, numkeys,
                 c->argv + 3 + numkeys, c->argc - 3 - numkeys);
    functionsScriptResetRun(&run_ctx);
}

/*
 * FCALL <FUNCTION NAME> nkeys <key1 .. keyn> <arg1 .. argn>
 */
void fcallCommand(client *c) {
    functionsLibCtx *live_ctx = curr_functions_lib_ctx;
    UNUSED(live_ctx);
    fcallCommandGeneric(c, functionsFcallIsReadonly(0));
}

/*
 * FCALL_RO <FUNCTION NAME> nkeys <key1 .. keyn> <arg1 .. argn>
 */
void fcallroCommand(client *c) {
    functionsLibCtx *live_ctx = curr_functions_lib_ctx;
    UNUSED(live_ctx);
    fcallCommandGeneric(c, functionsFcallIsReadonly(1));
}

