/* On script invocation, holding the current run context */
static scriptRunCtx *curr_run_ctx = NULL;

static void exitScriptTimedoutMode(scriptRunCtx *run_ctx) {
    serverAssert(run_ctx == curr_run_ctx);
    serverAssert(functionsScriptIsTimedout());
    run_ctx->flags = functionsFlagClear(run_ctx->flags, SCRIPT_TIMEDOUT);

    /* Get the number of arguments that are keys */
    if (getLongLongFromObjectOrReply(c,c->argv[2],&numkeys,NULL) != C_OK)
        return;
    if (numkeys > (c->argc - 3)) {
        addReplyError(c,"Number of keys can't be greater than number of args");
        return;
    } else if (numkeys < 0) {
        addReplyError(c,"Number of keys can't be negative");
        return;
    }

    evalCalcFunctionName(evalsha, c->argv[1]->ptr, funcname);

    /* Push the pcall error handler function on the stack. */
    lua_getglobal(lua, "__redis__err__handler");

    /* Try to lookup the Lua function */
    lua_getfield(lua, LUA_REGISTRYINDEX, funcname);
    if (lua_isnil(lua,-1)) {
        lua_pop(lua,1); /* remove the nil from the stack */
        /* Function not defined... let's define it if we have the
         * body of the function. If this is an EVALSHA call we can just
         * return an error. */
        if (evalsha) {
            lua_pop(lua,1); /* remove the error handler from the stack. */
            addReplyErrorObject(c, shared.noscripterr);
            return;
        }
        if (functionsLuaCreateFunction(c,c->argv[1]) == NULL) {
            lua_pop(lua,1); /* remove the error handler from the stack. */
            /* The error is sent to the client by functionsLuaCreateFunction()
             * itself when it returns NULL. */
            return;
        }
        /* Now the following is guaranteed to return non nil */
        lua_getfield(lua, LUA_REGISTRYINDEX, funcname);
        serverAssert(!lua_isnil(lua,-1));
    }

    char *lua_cur_script = funcname + 2;
    dictEntry *de = dictFind(lctx.lua_scripts, lua_cur_script);
    luaScript *l = dictGetVal(de);
    int ro = functionsEvalIsReadonlyCmd(c);

    scriptRunCtx rctx;
    if (functionsScriptPrepareForRun(&rctx, lua_client, c, lua_cur_script, l->flags, ro) != C_OK) {
        lua_pop(lua,2); /* Remove the function and error handler. */
        return;
    }
    rctx.flags |= SCRIPT_EVAL_MODE; /* mark the current run as EVAL (as opposed to FCALL) so we'll
                                      get appropriate error messages and logs */

    luaEngineInvokeEval(&rctx, lua, c->argv+3, numkeys, c->argv+3+numkeys, c->argc-3-numkeys, ldb.active);
    lua_pop(lua,1); /* Remove the error handler. */
    functionsScriptResetRun(&rctx);
}

void functionsEvalCommand(client *c) {
    lua_State *lua = lctx.lua;
    int debug_session = ldb.active;
    UNUSED(lua);
    UNUSED(debug_session);
    /* Explicitly feed monitor here so that lua commands appear after their
     * script command. */
    functionsFeedMonitorsForEval(c);
    if (!(c->flags & CLIENT_LUA_DEBUG))
        functionsEvalGenericCommand(c,0);
    else
        functionsEvalGenericCommandWithDebugging(c,0);
}

void functionsEvalRoCommand(client *c) {
    lua_State *lua = lctx.lua;
    UNUSED(lua);
    functionsEvalCommand(c);
}

void functionsEvalShaCommand(client *c) {
    lua_State *lua = lctx.lua;
    int debug_session = ldb.active;
    UNUSED(lua);
    UNUSED(debug_session);
    /* Explicitly feed monitor here so that lua commands appear after their
     * script command. */
    functionsFeedMonitorsForEval(c);
    if (!functionsCheckEvalShaLength(c->argv[1]->ptr)) {
        /* We know that a match is not possible if the provided SHA is
         * not the right length. So we return an error ASAP, this way
         * functionsEvalGenericCommand() can be implemented without string length
         * sanity check */
        addReplyErrorObject(c, shared.noscripterr);
        return;
    }
    if (!(c->flags & CLIENT_LUA_DEBUG))
        functionsEvalGenericCommand(c,1);
    else {
        addReplyError(c,"Please use EVAL instead of EVALSHA for debugging");
        return;
    }
}

void functionsEvalShaRoCommand(client *c) {
    lua_State *lua = lctx.lua;
    UNUSED(lua);
    functionsEvalShaCommand(c);

