s = s.replace('static void functionsFeedMonitorsForEval(client *c);', 'static void functionsFeedMonitorsForScript(client *c);')
s = s.replace('static void functionsFeedMonitorsForEval(client *c) {\n    /* EVAL-family commands are shown to MONITOR before nested writes. */', 'static void functionsFeedMonitorsForScript(client *c) {\n    /* Scripting commands are shown to MONITOR before nested commands. */')
s = s.replace('    functionsFeedMonitorsForEval(c);', '    functionsFeedMonitorsForScript(c);')
old = '''    scriptRunCtx run_ctx;

    if (functionsScriptPrepareForRun(&run_ctx, fi->li->ei->c, c, fi->name, fi->f_flags, ro) != C_OK)
        return;

    engine->call(&run_ctx, engine->engine_ctx, fi->function, c->argv + 3, numkeys,
                 c->argv + 3 + numkeys, c->argc - 3 - numkeys);
'''
new = '''    scriptRunCtx run_ctx;

    if (functionsScriptPrepareForRun(&run_ctx, fi->li->ei->c, c, fi->name, fi->f_flags, ro) != C_OK)
        return;

    /* Explicitly feed monitor here so that nested commands appear after FCALL. */
    functionsFeedMonitorsForScript(c);

    engine->call(&run_ctx, engine->engine_ctx, fi->function, c->argv + 3, numkeys,
                 c->argv + 3 + numkeys, c->argc - 3 - numkeys);
'''
assert old in s
s = s.replace(old, new)
p.write_text(s)
PY
grep -n "functionsFeedMonitors" src/functions.c

